import * as React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Container from '@mui/material/Container';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ArrowForward from '@mui/icons-material/ArrowForward';

/**
 * Hero Component
 * Main landing section of the website
 * Features a headline, description, and call-to-action buttons
 * Implements responsive design and accessibility features
 * @returns {JSX.Element} Hero section
 */
export default function Hero() {
  return (
    <section aria-label="Hero Section">
      <Box
        id="hero"
        sx={{
          width: '100%',
          backgroundImage: 'linear-gradient(180deg, rgba(18, 18, 18, 0.8) 0%, #121212 100%)',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          position: 'relative',
          pt: { xs: 14, sm: 20 },
          pb: { xs: 8, sm: 12 },
        }}
      >
        <Container
          sx={{
            position: 'relative',
            zIndex: 1,
          }}
        >
          <Stack
            spacing={4}
            alignItems="center"
            textAlign="center"
          >
            {/* Main Headline */}
            <Typography
              component="h1"
              variant="h1"
              sx={{
                fontSize: { xs: '2.5rem', sm: '3.5rem', md: '4rem' },
                fontWeight: 700,
                letterSpacing: '-0.02em',
                color: 'text.primary',
                maxWidth: '800px',
                lineHeight: { xs: 1.2, md: 1.1 },
              }}
            >
              Crafting Digital{' '}
              <Typography
                component="span"
                variant="inherit"
                sx={{
                  color: 'primary.main',
                  backgroundImage: 'linear-gradient(90deg, #90CAF9, #BBE3FF)',
                  backgroundClip: 'text',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                }}
              >
                Experiences
              </Typography>{' '}
              That Matter
            </Typography>

            {/* Subtitle */}
            <Typography
              variant="h4"
              component="p"
              sx={{
                color: 'text.secondary',
                maxWidth: '600px',
                fontSize: { xs: '1.125rem', sm: '1.25rem' },
                lineHeight: 1.6,
                mb: { xs: 2, sm: 4 },
              }}
            >
              We help businesses transform their ideas into impactful digital solutions through strategic design and development.
            </Typography>

            {/* Call to Action Buttons */}
            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              alignItems="center"
              spacing={{ xs: 2, sm: 3 }}
            >
              <Button
                variant="contained"
                color="primary"
                size="large"
                endIcon={<ArrowForward />}
                href="#contact"
                sx={{
                  minWidth: 200,
                  py: 1.5,
                  fontSize: '1.125rem',
                  fontWeight: 600,
                  transition: 'all 0.2s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-2px)',
                    boxShadow: (theme) => theme.shadows[4],
                  },
                }}
              >
                Book a Call
              </Button>
              <Button
                variant="outlined"
                color="primary"
                size="large"
                href="#portfolio"
                sx={{
                  minWidth: 200,
                  py: 1.5,
                  fontSize: '1.125rem',
                  fontWeight: 600,
                  borderWidth: 2,
                  '&:hover': {
                    borderWidth: 2,
                  },
                }}
              >
                View Portfolio
              </Button>
            </Stack>
          </Stack>
        </Container>

        {/* Background Gradient Overlay */}
        <Box
          sx={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            top: 0,
            left: 0,
            background: 'radial-gradient(circle at center, rgba(144, 202, 249, 0.1) 0%, rgba(18, 18, 18, 0) 70%)',
            pointerEvents: 'none',
          }}
        />
      </Box>
    </section>
  );
}
